246	     * household id contributing an empty segment. Two owners are duplicates only when
247	     * their whole identity keys are equal.
248	     */
249	    @Transient
250	    public String getIdentityKey() {
251	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
252	    }
253	
254	    private static String orEmpty(String value) {
255	        return value == null ? "" : value;
256	    }
257	
258	    public String getHouseholdId() {
259	        return this.householdId;
260	    }
261	
262	    public void setHouseholdId(String householdId) {
263	        this.householdId = householdId;
264	    }
265	
266	    public Integer getNamesakeCount() {
